// Goals form a real tree: CXO creates only the top ("enterprise") goal. Every
// level below it — ABU, then Department, then Employee — is generated by a
// mock "agent" and approved by the role that OWNS that level, not by CXO.
// That's the point: CXO approves once (which ABUs are involved); each ABU
// Head then separately approves their own department breakdown; each Dept
// Manager then separately approves their own employee breakdown. Responsibility
// for generating/approving is distributed down the chain, not centralized at CXO.
export type GoalLevel = "enterprise" | "abu" | "dept" | "employee";

export interface Goal {
  id: string;
  parentId: string | null;
  title: string;
  description: string;
  status: "active" | "at-risk" | "planning" | "done";
  targetDate: string;
  buId: string | null; // null = enterprise-wide
  deptId?: string;      // set on dept/employee-level goals
  assigneePersonId?: string; // set on employee-level (leaf) goals
  level: GoalLevel;
  // Governs generating/approving THIS goal's own children (the next level
  // down). Undefined = nothing in flight right now — the generate control
  // stays available afterward too, so it can be re-run to add more (this is
  // a showcase demo, not a one-shot gate).
  genState?: "generating" | "awaiting-approval";
  pendingChildren?: Goal[]; // generated but not yet approved; discarded on reject
}

