export function childrenOf(goalId: string, allGoals: Goal[]): Goal[] {
  return allGoals.filter((g) => g.parentId === goalId);
}

export function rootGoals(allGoals: Goal[]): Goal[] {
  return allGoals.filter((g) => g.parentId === null);
}
